import json, itertools, glob
from arena_kit.cost import total_cost, complete_offer, cost_breakdown
cases={c['case_id']:c for c in json.load(open('logs/cases/practice.json')) if c.get('hosted')}
best={}
for f in glob.glob('logs/sessions/practice/*.json'):
    s=json.load(open(f)); r=s.get('result') or {}
    if r.get('c_best'): best[s['case_id']]=(r['c_best'], r['c_open'])
def solve(case, terms, target):
    lo,hi=0.01, 10000
    for _ in range(80):
        mid=(lo+hi)/2
        if total_cost(case,{**terms,'unit_price':mid})>target: hi=mid
        else: lo=mid
    return lo
for cid,case in sorted(cases.items()):
    cb,co=best[cid]
    opts=case.get('term_options',{})
    fields=[f for f in case['negotiable'] if f!='unit_price' and opts.get(f)]
    rows=[]
    for combo in itertools.product(*[opts[f] for f in fields]):
        t=dict(zip(fields,combo))
        t=complete_offer(case,{**t,'unit_price':1.0})
        p=solve(case,t,cb); po=solve(case,t,co)
        rows.append((p,po,{f:(('IDX'+str(v['deadband_pct'])) if f=='index_clause' and v else v) for f,v in t.items() if f in fields}))
    rows.sort(key=lambda x:-x[0])
    print(cid, case['type'], case['buyer']['category_goal'], 'C_best',cb,'C_open',co)
    for p,po,t in rows[:6]: print(f'   P_best={p:9.3f} P_open={po:9.3f}  {t}')
