Usage: uv run python exp.py <name> ; experiments defined in EXPS below. Results appended to exp_results.jsonl."""

import json
import sys
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

from arena_kit import ArenaClient
from arena_kit.cli import load_env

OUT = Path(__file__).parent / "exp_results.jsonl"
BODY = (
    "Dear Sir or Madam,\n\nthank you for your message. Please find our proposal in the term sheet(s) attached to "
    "this e-mail.\n\nKind regards,\nHollerau Pumpenwerke, Purchasing"
)


def d01(price, pay=30, months=24, eff="2026-12-01"):
    return {"unit_price": round(price, 2), "payment_days": pay, "contract_months": months, "effective_date": eff}


def run(name, case_id, sid, policy, max_rounds=10, body=BODY, refs_fn=None, body_fn=None):
    client = ArenaClient()
    r = client.open_session(case_id)
    sess = r["session_id"]
    hist = []  # (our sheets, reply)
    opening = r["threads"][sid][-1]
    s_price = opening["term_sheets"][0]["terms"]["unit_price"]
    log = {"name": name, "session": sess, "case": case_id, "supplier": sid, "opening": opening["term_sheets"][0]["terms"], "rounds": []}
    print(name, "opened", sess, "quote", opening["term_sheets"][0]["terms"], flush=True)
    for rnd in range(1, max_rounds + 1):
        act = policy(rnd, hist, s_price)
        if act == "accept":
            res = client.send_message(sess, sid, {"action": {"type": "accept", "term_sheet_id": hist[-1][1]["term_sheets"][0]["term_sheet_id"]}})
            break
        if act == "walk":
            res = client.send_message(sess, sid, {"action": {"type": "walk_away"}})
            break
        sheets = act
        msg = {"subject": "Re: your offer", "body": body_fn(rnd, hist) if body_fn else body, "term_sheets": [{"terms": t} for t in sheets]}
        if refs_fn:
            msg["refs"] = refs_fn(rnd)
        t0 = time.time()
        rep = client.send_message(sess, sid, msg)
        dt = time.time() - t0
        hist.append((sheets, rep))
        sts = [ts["terms"] for ts in rep.get("term_sheets") or []]
        s_price = sts[0]["unit_price"] if sts else s_price
        log["rounds"].append({"round": rnd, "ours": sheets, "status": rep.get("status"), "theirs": sts, "claims": rep.get("claim_results"), "secs": round(dt, 1)})
        print(name, rnd, "ours", [t["unit_price"] for t in sheets], "->", rep.get("status"), [(t["unit_price"], {k: v for k, v in t.items() if k != "unit_price"}) for t in sts], f"{dt:.0f}s", flush=True)
        if rep.get("status") in ("walked_away", "no_bid"):
            break
    else:
        # out of rounds: accept the standing offer
        if hist and hist[-1][1].get("term_sheets"):
            client.send_message(sess, sid, {"action": {"type": "accept", "term_sheet_id": hist[-1][1]["term_sheets"][0]["term_sheet_id"]}})
    st = client.session(sess)
    res = st.get("result") or {}
    log["result"] = {k: res.get(k) for k in ("deal", "terms", "c_open", "c_deal", "c_best", "score")}
    log["reasons"] = [(t["round"], t["actor"], t.get("reasons")) for t in res.get("trace") or [] if t["actor"] != "buyer"]
    with OUT.open("a") as f:
        f.write(json.dumps(log) + "\n")
    print(name, "RESULT", json.dumps(log["result"]), flush=True)
    return log


# --- policies -------------------------------------------------------------------------------
def const(price, n=8, **kw):
    def p(rnd, hist, s):
        if rnd > n:
            return "accept"
        if hist and hist[-1][1].get("status") in ("agreed", "final_offer"):
            return "accept"
        return [d01(price, **kw)]
    return p


def linear(start, step, n=9, **kw):
    def p(rnd, hist, s):
        if hist and hist[-1][1].get("status") in ("agreed", "final_offer"):
            return "accept"
        if rnd > n:
            return "accept"
        price = min(start + step * (rnd - 1), s - 0.01)
        return [d01(price, **kw)]
    return p


def chase(start, delta, n=9, **kw):
    """Open at start, then always just `delta` below the supplier's last counter."""
    def p(rnd, hist, s):
        if hist and hist[-1][1].get("status") in ("agreed", "final_offer"):
            return "accept"
        if rnd > n:
            return "accept"
        price = start if rnd == 1 else s - delta
        return [d01(price, **kw)]
    return p


def halfgap(start, frac, n=9, **kw):
    """Open at start, then move `frac` of the remaining gap to the supplier's counter."""
    def p(rnd, hist, s):
        if hist and hist[-1][1].get("status") in ("agreed", "final_offer"):
            return "accept"
        if rnd > n:
            return "accept"
        if rnd == 1:
            price = start
        else:
            last = hist[-1][0][0]["unit_price"]
            price = last + frac * (s - last)
        return [d01(price, **kw)]
    return p


