    "d01_half47_03": lambda: run("d01_half47_03", "case:D01", "sup:DEMO-F1", halfgap(47.0, 0.3)),
    "d01_lin44_06": lambda: run("d01_lin44_06", "case:D01", "sup:DEMO-F1", linear(44.0, 0.6)),
}

