"""Numbers only: C of a sheet, what a sheet is worth to the supplier, the non-price terms we ask for
and, in relationship goals, the price below which a lower price costs us more than it saves.
Nothing here calls a model; every figure that reaches a term sheet comes from here."""

import itertools
import math

from arena_kit.cost import closing_terms, complete_offer, must_haves_ok, supplier_value, total_cost

RELATIONSHIP_GOALS = {"stabilise", "secure_supply"}


def cost(case, terms, std=None, est=None):
    """C in EUR; infinite for sheets the cost function cannot price."""
    try:
        return total_cost(case, terms, std, est)
    except (KeyError, TypeError, ValueError, ZeroDivisionError):
        return math.inf


def c_alt(case):
    alt = case["buyer"].get("alternative") or {}
    terms = alt.get("terms") or {}
    if alt.get("kind") in (None, "none") or not terms.get("unit_price"):
        return math.inf
    return cost(case, terms)


def acceptable(case, terms, std, est=None):
    """The accept gate: a price, every must-have kept, cheaper than the alternative."""
    return bool(terms.get("unit_price")) and must_haves_ok(case, terms, std) and cost(case, terms, std, est) < c_alt(case)


def estimate(case, std, rate, full_cost=None, ppm=None):
    """Our view of the supplier for `supplier_value` and the relationship term."""
    est = {"standard": closing_terms(case, {}, std), "interest_rate": rate}
    if ppm is not None:
        est["ppm"] = ppm
    if full_cost:
        est["full_cost"] = full_cost
    return est


def value(case, terms, est):
    """What a sheet is worth to the supplier per unit, in cash at its standard terms."""
    return supplier_value(case, terms, est)


def price_for_value(case, terms, est, target):
    """The unit price at which `terms` are worth `target` to the supplier (value rises with price)."""
    lo, hi = 0.0, max(1.0, target) * 3
    for _ in range(60):
        mid = (lo + hi) / 2
        if value(case, {**terms, "unit_price": mid}, est) < target:
            lo = mid
        else:
            hi = mid
    return hi


def options(case):
    """Every combination of allowed non-price values: [{field: value}]."""
    opts = case.get("term_options") or {}
    fields = [f for f in case["negotiable"] if f != "unit_price" and opts.get(f)]
    return [dict(zip(fields, combo, strict=True)) for combo in itertools.product(*(opts[f] for f in fields))]


def plan_terms(case, std, est, ref_terms, ref_price, keep=None):
    """The non-price terms that cost us least once the supplier prices them at its own valuation:
    for every allowed combination, the price worth the same to it as `ref_price` at `ref_terms`,
    then C at that price. `keep` pins fields. Returns (terms with that price, C)."""
    target = value(case, {**ref_terms, "unit_price": ref_price}, est)
    best = None
    for combo in options(case) or [{}]:
        if keep and any(combo.get(k, v) != v for k, v in keep.items()):
            continue
        terms = complete_offer(case, {**ref_terms, **combo, "unit_price": ref_price})
        terms["unit_price"] = round(price_for_value(case, terms, est, target), 2)
        if not must_haves_ok(case, terms, std):
            continue
        c = cost(case, terms, std, est)
        if best is None or c < best[1] - 0.5:
            best = (terms, c)
    return best


def at_price(case, terms, price):
    return {**terms, "unit_price": round(price, 2)}


def relationship_optimum(case, terms, std, est, lo, hi):
    """Relationship goals: the price in [lo, hi] with the lowest C, relationship charge included
    (C falls with price until the margin charge grows faster). Without a full-cost estimate: lo."""
    if case["buyer"].get("category_goal") not in RELATIONSHIP_GOALS or not est.get("full_cost"):
        return lo
    best_p, best_c = lo, math.inf
    steps = 200
    for i in range(steps + 1):
        p = lo + (hi - lo) * i / steps
        c = cost(case, at_price(case, terms, p), std, est)
        if c < best_c - 1e-6:
            best_p, best_c = p, c
    return round(best_p, 2)

"""Data arguments, each one sentence with its figure next to its IDs, computed the way the arena
checks them (`docs/api.md`, What counts). Only arguments that push the price our way are kept;
a rising index or a should-cost above the quote would argue the supplier's case.

In the sandbox the case's refs point into a demo world our package does not hold: those are cited
without a figure, so the arena checks them against their own value."""

import re

ID_RE = re.compile(r"\b(?:idx|quote|offer|sc|qn|po|cost|fc|news|doc|ctr):[\w.:@#/-]*\w")
SERIES_NAME = {
    "PPI-C2451": "Producer prices for iron castings",
    "PPI-C2452": "Producer prices for steel castings",
    "PPI-C2562": "Producer prices for machining",
    "PPI-C2594": "Producer prices for fasteners",
    "PPI-C2711": "Producer prices for electric motors",
    "PPI-C2611": "Producer prices for electronic components",
    "PPI-C2815": "Producer prices for bearings and gears",
    "PPI-C241": "Producer prices for basic iron and steel",
    "PPI-C2431": "Producer prices for cold-drawn bars",
    "PPI-C2219": "Producer prices for rubber products",
    "PPI-D351": "Electricity producer prices",
    "PPI-D35": "Energy supply producer prices",
    "LCI-C": "Manufacturing labour costs",
    "WB-CU": "Copper",
    "WB-NI": "Nickel",
    "WB-AL": "Aluminium",
    "WB-NGEU": "European natural gas",
    "CU-NOTATION": "The copper notation",
    "AS-14404": "The 1.4404 alloy surcharge",
    "AS-14301": "The 1.4301 alloy surcharge",
}


def months_back(month, n):
    y, m = (int(x) for x in month.split("-"))
    m -= n
    while m <= 0:
        m, y = m + 12, y - 1
    return f"{y}-{m:02d}"


def money(x):
    return f"EUR {x:.2f}"


class ClaimBank:
    """Arguments for one case. `pkg` is the data package (or None); the case's own `facts` win."""

    def __init__(self, pkg, case):
        self.pkg, self.case = pkg, case
        self.facts = case.get("facts") or {}
        self.refs = list(case.get("refs") or [])
        # a case whose refs the package does not know (the sandbox's demo world)
        self.foreign = bool(self.refs) and pkg is not None and not any(pkg.lookup(r) for r in self.refs)

    def fact(self, ref):
        if ref in self.facts:
            return self.facts[ref]
        return None if self.foreign or self.pkg is None else self.pkg.lookup(ref)

    def ids(self, prefix):
        out = set() if self.foreign or self.pkg is None else set(self.pkg.ids(prefix))
        out |= {k for k in self.facts if k.startswith(prefix)}
        out |= {r for r in self.refs if r.startswith(prefix)}
        return sorted(out)

    def query(self, sql, params=()):
        if self.foreign or self.pkg is None:
            return []
        try:
            return self.pkg.query(sql, params)
        except Exception:  # noqa: BLE001 - a package without SQLite: facts only
            return []

    # -- single arguments ------------------------------------------------------------------
    def should_cost(self, part, sid, quote):
        best = None
        for ref in self.ids("cost:"):
            f = self.fact(ref)
            if not f or f.get("part") != part or not f.get("unit_cost"):
                continue
            if ref.endswith("-" + sid.split(":")[-1]):
                best = (ref, f)
                break
            if best is None and "-" not in ref.split(":")[-1]:
                best = (ref, f)
        if not best:
            return None
        ref, f = best
        if quote and f["unit_cost"] >= quote * 0.98:
            return None  # above or near its price: argues its case
        return {
            "kind": "should_cost",
            "ids": [ref],
            "text": f"Our bottom-up should-cost estimate for this part is {money(f['unit_cost'])} per unit ({ref}).",
            "strength": 5,
        }

    def order_history(self, part, sid, quote):
        rows = self.query(
            "SELECT id FROM po_lines WHERE part_id = ? AND supplier_id = ? ORDER BY order_date DESC LIMIT 3",
            (part, sid),
        )
        facts = [(r["id"], self.fact(r["id"])) for r in rows]
        facts = [(i, f) for i, f in facts if f and f.get("unit_price")]
        if len(facts) < 2:
            return None
        prices = [f["unit_price"] for _, f in facts]
        if quote and min(prices) >= quote:
            return None
        ids = [i for i, _ in facts]
        if len(set(prices)) == 1:
            text = f"Our last {len(ids)} orders for this part were at {money(prices[0])} ({', '.join(ids)})."
        else:
            text = f"Our last orders for this part were at {' and '.join(money(p) for p in prices)} ({', '.join(ids)})."
        return {"kind": "order_history", "ids": ids, "text": text, "strength": 4}

    def notice(self, sid):
        doc = self.case.get("trigger_doc")
        f = self.fact(doc) if doc else None
        if not f or f.get("days") is None:
            return None
        ctr = next((r for r in self.refs if r.startswith("ctr:") and "#" not in r), None)
        c = self.fact(ctr) if ctr else None
        if not c or c.get("days") is None or f["days"] >= c["days"]:
            return None
        text = f"Your letter gives {f['days']} days' notice ({doc}); our agreement provides for {c['days']} days ({ctr})."
        return {"kind": "notice", "ids": [doc, ctr], "text": text, "strength": 5}

    def index_change(self, series):
        ids = self.ids(f"idx:{series}@")
        if not ids:
            return None
        m2 = ids[-1].split("@")[-1]
        m1 = months_back(m2, 12)
        a, b = self.fact(f"idx:{series}@{m1}"), self.fact(f"idx:{series}@{m2}")
        if not a or not b or not a.get("value"):
            return None
        pct = (b["value"] / a["value"] - 1) * 100
        if pct > -0.5:
            return None  # a rising driver confirms the supplier's case
        name = SERIES_NAME.get(series, f"The index {series}")
        return {
            "kind": "index",
            "ids": [f"idx:{series}@{m1}", f"idx:{series}@{m2}"],
            "text": f"{name} changed {pct:.1f}% from {m1} to {m2} (idx:{series}@{m1}, idx:{series}@{m2}).",
            "strength": 3 + min(3.0, abs(pct) / 3),
        }

    def drivers(self, part):
        return [r["series_id"] for r in self.query("SELECT series_id FROM cost_drivers WHERE part_id = ?", (part,))]

    def forecast(self, part):
        ids = self.ids(f"fc:{part.split(':')[-1]}@")
        f = self.fact(ids[-1]) if ids else None
        if not f or (f.get("change_pct") or 0) <= 0:
            return None
        text = f"Our forecast for this part is up {f['change_pct']:.1f}% ({ids[-1]})."
        return {"kind": "forecast", "ids": [ids[-1]], "text": text, "strength": 2}

    def rival_quote(self, part, sid, price):
        """A quote of this case from another supplier, cheaper than this supplier's price."""
        out = []
        for ref in self.refs:
            f = self.fact(ref) if ref.startswith("quote:") else None
            if f and f.get("part") == part and f.get("supplier") != sid and price and f["unit_price"] < price:
                out.append(
                    {
                        "kind": "rival",
                        "ids": [ref],
                        "text": f"We hold another quote for this part at {money(f['unit_price'])} per unit ({ref}).",
                        "strength": 6,
                        "rival": True,
                    }
                )
        return out

    def scorecard(self, sid, quality):
        ids = self.ids(f"sc:{sid.split(':')[-1]}@")
        if not ids:
            return None
        f = self.fact(ids[-1])
        if f is None:  # demo world: cite without a figure
            text = f"We have reviewed your delivery performance in our supplier scorecard ({ids[-1]})."
            return {"kind": "scorecard", "ids": [ids[-1]], "text": text, "strength": 2}
        if quality:
            if (f.get("ppm") or 0) < 1000:
                return None
            text = f"Your deliveries ran at {f['ppm']} ppm in {f['quarter']} ({ids[-1]})."
        else:
            if (f.get("otd_pct") or 100) >= 90:
                return None
            text = f"Your on-time delivery was {f['otd_pct']}% in {f['quarter']} ({ids[-1]})."
        return {"kind": "scorecard", "ids": [ids[-1]], "text": text, "strength": 2}

    def demo_refs(self):
        """Refs the package cannot resolve: cited without a figure."""
        words = {
            "cost": ("should_cost", "Our bottom-up should-cost estimate for this part is on file ({ids}).", 5),
            "po": ("order_history", "We compared your offer with our recent order prices for this part ({ids}).", 4),
        }
        out = []
        for kind, (name, text, strength) in words.items():
            ids = [r for r in self.refs if r.startswith(f"{kind}:") and self.fact(r) is None]
            if ids:
                out.append({"kind": name, "ids": ids[:3], "text": text.format(ids=", ".join(ids[:3])), "strength": strength})
        doc = self.case.get("trigger_doc")
        ctr = next((r for r in self.refs if r.startswith("ctr:")), None)
        if doc and ctr and self.fact(doc) is None and self.case.get("type") == "price_increase":
            text = f"Your letter ({doc}) gives less notice than our agreement provides for ({ctr})."
            out.append({"kind": "notice", "ids": [doc, ctr], "text": text, "strength": 5})
        return out

    # -- per supplier ----------------------------------------------------------------------
    def for_supplier(self, sid, quote):
        """Every argument for this supplier that pushes our way, strongest first."""
        case, out = self.case, []
        quality = case.get("type") == "quality" or case["buyer"].get("category_goal") == "quality_first"
        for part in case.get("parts") or []:
            out += [c for c in (self.should_cost(part, sid, quote), self.order_history(part, sid, quote)) if c]
            out += [c for c in (self.index_change(s) for s in self.drivers(part)) if c]
            out += self.rival_quote(part, sid, quote)
            if c := self.forecast(part):
                out.append(c)
        if c := self.notice(sid):
            out.append(c)
        if c := self.scorecard(sid, quality):
            out.append(c)
        if self.foreign:
            out += self.demo_refs()
        seen, uniq = set(), []
        for c in sorted(out, key=lambda c: -c["strength"]):
            if tuple(c["ids"]) not in seen:
                seen.add(tuple(c["ids"]))
                uniq.append(c)
        return uniq


def rival_offer(sid, offer_id, price):
    """Another bidder's standing offer in this session, citable to the others."""
    return {
        "kind": "rival",
        "ids": [offer_id],
        "text": f"Another bidder offers {money(price)} per unit for this part ({offer_id}).",
        "strength": 7,
        "rival": True,
        "from": sid,
    }

"""E-mails from templates: every figure and ID comes from code, the wording stays polite and
factual. Never mentions urgency, a budget, our alternative's absence or our target."""

FIELDS = {
    "payment_days": lambda v: f"payment {v} days net",
    "contract_months": lambda v: f"{v} months" if v else "a single order",
    "volume_per_year": lambda v: f"{v} units a year",
    "lead_time_days": lambda v: f"lead time {v} days",
    "effective_date": lambda v: f"valid from {v}",
    "incoterm": lambda v: f"delivery {v}",
    "tooling_eur": lambda v: f"tooling EUR {v:.0f}" if v else "no tooling charge",
    "ppm_commitment": lambda v: f"{v} ppm",
    "chargeback_eur_per_complaint": lambda v: f"chargeback EUR {v:.0f} per complaint",
    "index_clause": lambda v: (
        f"price follows {v['series']} on {round(v['material_share'] * 100)}% of the price, "
        f"deadband {v['deadband_pct']}%"
        if v
        else "fixed price"
    ),
}


def describe(case, sheet):
    parts = [f"EUR {sheet['unit_price']:.2f} per unit"]
    for field in case["negotiable"]:
        if field != "unit_price" and field in sheet and field in FIELDS:
            parts.append(FIELDS[field](sheet[field]))
    return ", ".join(parts)


def email(case, sheets, claims, question=None, first=False, moved=False, warm=True):
    lines = ["Dear Sir or Madam,", ""]
    if first:
        lines.append("Thank you for your offer and for the time your team has put into it.")
    elif moved:
        lines.append("Thank you for your reply and for the step you have taken.")
    else:
        lines.append("Thank you for your reply.")
    if warm:
        lines.append("We value our cooperation and would like to reach an agreement that works for both sides.")
    if claims:
        lines.append("")
        lines += [c["text"] for c in claims]
    lines.append("")
    if len(sheets) == 1:
        lines.append(f"On this basis we propose: {describe(case, sheets[0])}.")
    else:
        lines.append("On this basis we propose one of these packages:")
        lines += [f"- Option {chr(65 + i)}: {describe(case, s)}" for i, s in enumerate(sheets)]
    if question:
        lines += ["", question]
    lines += ["", "Kind regards,", "Hollerau Pumpenwerke, Purchasing"]
    return "\n".join(lines)


def keepalive():
    return (
        "Dear Sir or Madam,\n\nthank you for your offer, which we are reviewing internally. Could you confirm "
        "how long it remains valid?\n\nKind regards,\nHollerau Pumpenwerke, Purchasing"
    )

"""Plays cases with the policy. Each supplier thread has its own worker that answers a reply at
once (every thread's 60-second clock runs on its own), finished threads are kept alive while the
others negotiate, then the cheapest acceptable sheet is accepted. Same hosted arena, sandbox,
practice or final; `play_waves` is the kit's Live Final loop with this runner."""

import functools
import json
import logging
import threading
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

from arena_kit.client import ArenaError
from arena_kit.play import ENDED, RemoteTable, fetch_documents, latest, moves_left, quota_used_up

from .policy import DONE, Negotiator, deadline_near, keepalive_message

log = logging.getLogger("buyer")
RUNS = Path("logs/runs")
KEEPALIVE_AFTER_S = 40  # a waiting thread gets a question this long after the supplier's reply
RESERVE = 2  # in an RFQ, messages a thread keeps for keepalives while the others negotiate


def play_case(table, case_id, pkg=None, deadline=None):
    case, threads = table.open(case_id)
    if getattr(table, "done", None):  # resumed a case that had already ended
        return table.done
    for events in threads.values():
        for m in events:
            fetch_documents(table, m)
    neg = Negotiator(case, pkg)
    for sid, events in threads.items():
        neg.setup(sid, events)
    lock, ended = threading.Lock(), threading.Event()
    rfq = len(threads) > 1
    replied = {sid: time.monotonic() for sid in threads}
    result = {}

    def send(sid, message):
        try:
            reply = table.send(sid, message)
        except ArenaError as e:
            if e.status != 409:
                raise
            log.info("%s %s: %s", case_id, sid, e.detail)
            reply = table.missed(sid, e)
            if "result" in reply:
                result.setdefault("r", reply["result"])
                ended.set()
                return False
        fetch_documents(table, reply)
        with lock:
            threads[sid] += [{**message, "from": "buyer"}, reply]
            replied[sid] = time.monotonic()
        return True

    def all_done():
        with lock:
            return all(latest(ev).get("status") in ENDED | DONE or neg.sides[s].state != "open" for s, ev in threads.items())

    def worker(sid):
        while not ended.is_set() and not deadline_near(deadline):
            with lock:
                if rfq and moves_left(case, threads[sid]) <= RESERVE:
                    neg.sides[sid].state = "done"
                    move = None
                else:
                    move = neg.move(sid, threads)
            if move is None or not send(sid, move["message"]):
                break
        while rfq and not ended.is_set() and not all_done() and not deadline_near(deadline):
            with lock:
                status = latest(threads[sid]).get("status")
                left = moves_left(case, threads[sid])
                waited = time.monotonic() - replied[sid]
            if status in ENDED:
                return
            if waited >= KEEPALIVE_AFTER_S and left > 0:
                if not send(sid, keepalive_message(threads[sid])):
                    return
            time.sleep(1)

    with ThreadPoolExecutor(max_workers=len(threads)) as pool:
        list(pool.map(worker, list(threads)))
    if result:
        out = result["r"]
    else:
        decision = neg.close(threads)
        out = table.close(decision["supplier_id"], decision["message"])
    save(table.session_id, case_id, neg, out)
    return out


def save(session_id, case_id, neg, result):
    RUNS.mkdir(parents=True, exist_ok=True)
    keep = ("deal", "supplier_id", "terms", "c_open", "c_deal", "c_best", "score")
    path = RUNS / f"{case_id.split(':')[-1]}_{session_id}.json"
    path.write_text(json.dumps({"case": case_id, "session": session_id, "notes": neg.notes,
                                "result": {k: result.get(k) for k in keep}}, indent=1, default=str))


def play_all(client, case_ids, pkg=None, parallel=8):
    """Practice or sandbox: many cases at once. {case_id: result or the exception that stopped it}."""
    used_up = threading.Event()

    def one(case_id):
        if used_up.is_set():
            return case_id, ArenaError(429, "not started: the practice quota is used up")
        try:
            return case_id, play_case(RemoteTable(client), case_id, pkg)
        except ArenaError as e:
            if quota_used_up(e):
                used_up.set()
            log.warning("%s: %s", case_id, e)
            return case_id, e
        except Exception as e:  # one broken case must not stop the others
            log.exception("%s failed", case_id)
            return case_id, e

    with ThreadPoolExecutor(max_workers=parallel) as pool:
        return dict(pool.map(one, case_ids))


def play_waves(client, pkg=None, waves=5, parallel=10, poll=5.0):
    """The Live Final: wait for each wave, play its cases in parallel within the wave's cap."""
    started, closed, caps = {}, set(), {}

    def one(case, deadline):
        try:
            return play_case(RemoteTable(client, case), case["case_id"], pkg, deadline)
        except Exception as e:  # one broken case must not stop the others
            log.exception("%s failed", case["case_id"])
            return e

    with ThreadPoolExecutor(max_workers=parallel) as pool:
        while len(closed) < waves or not all(f.done() for f in started.values()):
            try:
                cases = client.cases("final")
            except ArenaError as e:
                if e.status != 403:  # 403: no wave has started yet
                    raise
                cases = []
            for case in cases:
                if not case.get("open"):
                    closed.add(case["wave"])
                    continue
                if case.get("seconds_left") is not None:
                    caps[case["wave"]] = time.time() + case["seconds_left"]
                if case["case_id"] not in started and case.get("seconds_left"):
                    log.warning("wave %s: %s", case["wave"], case["case_id"])
                    started[case["case_id"]] = pool.submit(one, case, functools.partial(caps.get, case["wave"]))
            time.sleep(poll)
    return {case_id: f.result() for case_id, f in started.items()}

